  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C35"],
      "claim": "Indomethacin, a highly transferable analogue sharing indole/chlorophenyl/methoxy features, has 98% absolute oral bioavailability in adults, supporting F≥20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Rigosertib, a large polar aromatic drug with methoxy groups, showed 35% absolute oral bioavailability in fasting patients, directly above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Omeprazole, a heteroaromatic drug with methoxy and polar groups, has 30–40% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Loratadine, a tricyclic chloroaromatic drug, has good oral bioavailability in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C38"],
      "claim": "GDC-0810, a large carboxylic-acid-containing aromatic drug, was predicted to have ~45% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Midodrine, a dimethoxyphenyl drug, has 93% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Alfuzosin, a dimethoxyquinazoline diamine with an amide side chain, has 64.5% absolute oral bioavailability in healthy subjects, structurally relevant to the query's aminopyrimidine/dimethoxy features.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Colchicine, a trimethoxy/acetamide drug, has mean 55% absolute oral bioavailability, supporting high F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All highly transferable experimental analogues report absolute oral bioavailability values above 20% (mostly 35–98%), strongly supporting a high F≥20% prediction; the physicochemical low-F prior is overridden by direct human bioavailability evidence.",
  "evidence_gaps": [
    "No direct human pharmacokinetic data exist for the query molecule itself.",
    "The query has higher molecular weight and TPSA than most analogues, so solubility-limited absorption is not directly measured.",
    "Food effects and formulation dependence are unknown for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

